    pv_d_usage_x: { zh: "：每月匯出次數、匯出格式、方案（免費/VIP）狀態、訂單紀錄。", en: ": monthly export counts, export formats, plan (free/VIP) status and order records.", ja: "：月間エクスポート回数、エクスポート形式、プラン（無料/VIP）状態、注文履歴。", ko: ": 월별 내보내기 횟수, 내보내기 형식, 플랜(무료/VIP) 상태, 주문 기록." },
    pv_d_tech: { zh: "技術資料", en: "Technical data", ja: "技術データ", ko: "기술 데이터" },
    pv_d_tech_x: { zh: "：錯誤紀錄、瀏覽器資訊、請求時間與系統日誌（除錯與安全防護用）。", en: ": error logs, browser information, request times and system logs (for debugging and security).", ja: "：エラーログ、ブラウザ情報、リクエスト時刻、システムログ（デバッグとセキュリティ用）。", ko: ": 오류 로그, 브라우저 정보, 요청 시각, 시스템 로그(디버깅 및 보안용)." },
    pv_d_local: { zh: "本機儲存", en: "Local storage", ja: "ローカル保存", ko: "로컬 저장" },
    pv_d_local_x: { zh: "：登入憑證（token）與未登入時的專案暫存，存於瀏覽器 localStorage。", en: ": the sign-in token and, when signed out, a temporary copy of your project — both in the browser's localStorage.", ja: "：ログイン用トークンと、未ログイン時のプロジェクト一時保存。ブラウザの localStorage に保存されます。", ko: ": 로그인 토큰과 비로그인 상태의 프로젝트 임시 저장. 브라우저 localStorage에 보관됩니다." },
    pv_d_card: { zh: "本站不經手、不儲存您的信用卡號或任何卡片資料", en: "This site never handles or stores your card number or any card data", ja: "当サイトはクレジットカード番号やカード情報を一切扱わず、保存もしません", ko: "본 사이트는 신용카드 번호나 카드 정보를 취급하거나 저장하지 않습니다" },
    pv_d_card_x: { zh: "；本站僅保存訂單編號、方案、金額與付款狀態，用於開通服務與對帳。", en: "; only the order number, plan, amount and payment status are kept, for activating the service and reconciliation.", ja: "；保存するのは注文番号・プラン・金額・支払状態のみで、サービス有効化と照合に使用します。", ko: "; 주문 번호, 플랜, 금액, 결제 상태만 보관하며 서비스 개통과 대사에 사용합니다." },
    pv_d_ai: { zh: "使用該功能時，相關電路資料會傳送至 AI 模型供應商處理", en: "When you use that feature, the relevant circuit data is sent to the AI model provider for processing", ja: "この機能を使うと、該当する回路データが AI モデル提供者に送信され処理されます", ko: "해당 기능을 사용하면 관련 회로 데이터가 AI 모델 제공업체로 전송되어 처리됩니다" },
    pv_d_ai_x: { zh: "；不使用則不傳送。", en: "; nothing is sent if you do not use it.", ja: "；使用しなければ送信されません。", ko: "; 사용하지 않으면 전송되지 않습니다." },
    tm_ds: { zh: "投產前請務必以原廠 datasheet 為準", en: "Always defer to the manufacturer's datasheet before going to production", ja: "量産前には必ずメーカーのデータシートを優先してください", ko: "양산 전에는 반드시 제조사 데이터시트를 기준으로 하세요" },
    tm_ds_x: { zh: "；因使用本站資料造成之損失，本站不負賠償責任。", en: "; this site accepts no liability for losses arising from use of its data.", ja: "；当サイトのデータ利用により生じた損害について、当サイトは責任を負いません。", ko: "; 본 사이트 데이터 사용으로 발생한 손실에 대해 책임지지 않습니다." },

    ix_pin_hint: { zh: "Pin 表（每行：編號,名稱,側別(L/R/T/B),類型；側別/類型可省略；# 註解）", en: "Pin table (one per line: number, name, side (L/R/T/B), type; side and type are optional; # starts a comment)", ja: "ピン表（1 行につき：番号, 名前, 側(L/R/T/B), 種別；側と種別は省略可；# はコメント）", ko: "핀 표(한 줄에: 번호, 이름, 측면(L/R/T/B), 종류; 측면과 종류는 생략 가능; #는 주석)" },
    pv_brd_note: { zh: ".brd 為 Cadence 專有二進位：本工具讀「SKILL 匯出的中繼 JSON」，改板用產出的 SKILL 腳本回 Allegro 執行", en: ".brd is a Cadence proprietary binary. This tool reads the intermediate JSON exported by SKILL; edits go back to Allegro as a generated SKILL script.", ja: ".brd は Cadence 独自のバイナリです。本ツールは SKILL が書き出した中間 JSON を読み、変更は生成した SKILL スクリプトで Allegro に戻します。", ko: ".brd는 Cadence 독점 바이너리입니다. 이 도구는 SKILL이 내보낸 중간 JSON을 읽고, 변경은 생성된 SKILL 스크립트로 Allegro에 반영합니다." },
    ip_note: { zh: "引擎 ic-symbol.js + 資料 ic-data.js。仿 datasheet Pin Configuration：腳號在框內、腳名在框外、上下腳名垂直、Thermal Pad 補 GND 腳。", en: "Engine ic-symbol.js + data ic-data.js. Drawn like a datasheet Pin Configuration: pin numbers inside the box, pin names outside, top and bottom names vertical, thermal pad added as a GND pin.", ja: "エンジン ic-symbol.js＋データ ic-data.js。データシートの Pin Configuration に倣う：ピン番号は枠内、ピン名は枠外、上下のピン名は縦書き、サーマルパッドは GND ピンとして追加。", ko: "엔진 ic-symbol.js + 데이터 ic-data.js. 데이터시트의 Pin Configuration 방식: 핀 번호는 박스 안, 핀 이름은 박스 밖, 위아래 핀 이름은 세로, 서멀 패드는 GND 핀으로 추가." },

    pcb_colors: { zh: "🎨 整體配色", en: "🎨 Colours", ja: "🎨 配色", ko: "🎨 색상" },
    pcbf_h_colors: { zh: "改的是全域預設色。單一走線／元件可在「選取元件」面板單獨上色，會蓋過這裡。", en: "These are the global defaults. A single trace or part can be coloured in the “Selection” panel, which overrides this.", ja: "ここで変えるのは全体の既定色です。個々の配線や部品は「選択」パネルで個別に色を付けられ、そちらが優先されます。", ko: "여기서 바꾸는 것은 전역 기본 색상입니다. 개별 배선이나 부품은 “선택” 패널에서 따로 지정할 수 있고 그쪽이 우선합니다." },
    pcbf_palreset: { zh: "還原預設配色", en: "Reset the palette", ja: "配色を既定に戻す", ko: "색상을 기본값으로 되돌리기" },
    ix_colorlock: { zh: "🔒 鎖色", en: "🔒 Lock colour", ja: "🔒 色ロック", ko: "🔒 색상 고정" },
    ix_t_colorlock: { zh: "鎖色：之後新叫的元件與新畫的線都用這個顏色，選到元件也不會被蓋掉", en: "Lock the colour: new parts and new wires all use it, and selecting a part no longer overwrites it", ja: "色ロック：以降に置く部品と描く配線はこの色になり、部品を選んでも上書きされません", ko: "색상 고정: 이후 배치하는 부품과 그리는 배선이 이 색을 쓰며, 부품을 선택해도 덮어쓰지 않습니다" },
