    drc_courtyard:  { zh: 'courtyard 重疊：{a} ↔ {b} @({x},{y})', en: 'Courtyard overlap: {a} ↔ {b} @({x},{y})', ja: 'コートヤード重なり：{a} ↔ {b} @({x},{y})', ko: '코트야드 겹침: {a} ↔ {b} @({x},{y})' },
