    drc_cat_ring:      { zh: '環寬', en: 'Annular ring', ja: 'アニュラリング', ko: '애뉼러 링' },
    drc_cat_via_ring:  { zh: 'via環寬', en: 'Via annular ring', ja: 'ビアのアニュラリング', ko: '비아 애뉼러 링' },
