    pj_drc_thin:     { zh: '走線寬度過細：{w}mm < {lim}mm', en: 'Trace too thin: {w}mm < {lim}mm', ja: '配線が細すぎ：{w}mm < {lim}mm', ko: '배선이 너무 얇음: {w}mm < {lim}mm' },
    pj_drc_use_via:  { zh: '建議使用 Via 進行層間連接', en: 'Consider using vias for inter-layer connections', ja: '層間接続にはビアの使用を推奨', ko: '층간 연결에 비아 사용 권장' },
