    sm_why_unterminated: { zh: '有實體沒有結尾分號', en: 'an entity is not terminated', ja: '終端されていない実体があります', ko: '종료되지 않은 엔티티가 있습니다' },
    sm_why_tooLarge: { zh: '檔案太大', en: 'the file is too large', ja: 'ファイルが大きすぎます', ko: '파일이 너무 큽니다' },
    sm_nosolid: { zh: '「{name}」裡沒有實體（MANIFOLD_SOLID_BREP），匯出後會是空的', en: '“{name}” has no solid (MANIFOLD_SOLID_BREP); the export would be empty', ja: '「{name}」にソリッド（MANIFOLD_SOLID_BREP）がなく、書き出しても空になります', ko: '“{name}”에 솔리드(MANIFOLD_SOLID_BREP)가 없어 내보내도 비어 있게 됩니다' },
    sm_quota: { zh: '瀏覽器儲存空間不足，模型沒有存進去', en: 'Browser storage is full, so the model was not saved', ja: 'ブラウザの保存領域が不足しており、モデルは保存されませんでした', ko: '브라우저 저장 공간이 부족하여 모델이 저장되지 않았습니다' },
    sm_read_failed: { zh: '讀不到「{name}」', en: 'Could not read “{name}”', ja: '「{name}」を読み込めません', ko: '“{name}”을(를) 읽을 수 없습니다' },
    sm_bound: { zh: '已把「{name}」綁到 {key}（{n} 個實體）', en: 'Bound “{name}” to {key} ({n} solids)', ja: '「{name}」を {key} に紐付けました（実体 {n} 個）', ko: '“{name}”을(를) {key}에 연결했습니다(솔리드 {n}개)' },
    sm_ask_del: { zh: '要解除「{name}」的綁定嗎？', en: 'Unbind “{name}”?', ja: '「{name}」の紐付けを解除しますか？', ko: '“{name}” 연결을 해제할까요?' },
