    sm_ask_scale: { zh: '「{name}」的縮放倍率（單位不對時用；公制模型通常是 1）', en: 'Scale factor for “{name}” (use when the units are wrong; metric models are usually 1)', ja: '「{name}」の倍率（単位が合わないときに使用。メートル法のモデルは通常 1）', ko: '“{name}”의 배율(단위가 맞지 않을 때 사용, 미터법 모델은 보통 1)' },
    sm_bad_scale: { zh: '倍率要是大於 0 的數字', en: 'The scale must be a number greater than 0', ja: '倍率は 0 より大きい数値である必要があります', ko: '배율은 0보다 큰 숫자여야 합니다' },
